<?php if($canManage):$selectedPayment=$detailed==='partial'?'signal_paid':$r['payment_status'];?><form method="post" action="/sports/reservations/<?=(int)$r['id']?>/update" class="row g-2 mt-2"><?=CSRF::field()?><div class="col-md-5"><select class="form-select" name="status"><?php foreach($status as $key=>$label):?><option value="<?=$key?>" <?=$r['status']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-5"><select class="form-select" name="payment_status"><?php foreach($payments as $key=>$label):?><option value="<?=$key?>" <?=$selectedPayment===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Salvar</button></div></form><?php if(in_array($r['status'],['pending_payment','confirmed'],true)):?><details class="mt-2"><summary class="small text-primary" style="cursor:pointer">Remarcar</summary><form method="post" action="/sports/reservations/<?=(int)$r['id']?>/reschedule" class="row g-2 mt-2"><?=CSRF::field()?><div class="col-md-6"><input class="form-control" type="datetime-local" name="starts_at" required></div><div class="col-md-3"><input class="form-control" type="number" name="duration_minutes" value="<?=(int)$r['duration_minutes']?>" min="15" step="15"></div><div class="col-md-3"><button class="btn btn-outline-secondary w-100">Remarcar</button></div></form></details><?php endif;?><?php endif;?>
