<script>
(function(){const court=document.getElementById('arenaReservationCourt'),mod=document.getElementById('arenaReservationModality');if(!court||!mod)return;function sync(){let first=null;for(const o of mod.options){const ok=o.dataset.court===court.value;o.hidden=!ok;o.disabled=!ok;if(ok&&!first)first=o;}if(mod.selectedOptions[0]?.disabled&&first)mod.value=first.value;}court.addEventListener('change',sync);sync();})();
</script>
